from pydantic import ValidationError
from tools.client import DonorNotFound, CrmError
from tools.errors import error_result

try:
    args = tool.input_model.model_validate(arguments)
except ValidationError as e:
    fields = sorted({str(err["loc"][0]) for err in e.errors() if err["loc"]})
    return error_result("invalid_arguments", f"Invalid arguments: {', '.join(fields)}", fields=fields)
try:
    return tool.handler(args)
except DonorNotFound as e:
    return error_result("not_found", str(e), suggestion="Use find_donor first.", donor_id=e.donor_id)
except CrmError as e:
    return error_result("upstream_error", str(e))

